import threading, random
from inventory import Inventory, MemoryStore, OutOfStock
for trial in range(20):
    skus = {f"S{i}": 100 for i in range(5)}
    inv = Inventory(MemoryStore(dict(skus)))
    taken = {k: 0 for k in skus}
    lock = threading.Lock()
    def worker():
        for _ in range(200):
            s = random.choice(list(skus))
            try:
                inv.reserve(s, 1)
            except OutOfStock:
                continue
            with lock:
                taken[s] += 1
            if random.random() < 0.5:
                inv.release(s, 1)
                with lock:
                    taken[s] -= 1
    ts = [threading.Thread(target=worker) for _ in range(8)]
    [t.start() for t in ts]; [t.join() for t in ts]
    for s in skus:
        assert inv.available(s) == 100 - taken[s], (s, inv.available(s), taken[s])
        assert inv.available(s) >= 0
print("stress ok: no oversell, balances consistent")
